  1	//! `callisto init`: report detected facts, ask only for intent, preview the first release, then write.
  2	
  3	use std::io::Write;
  4	use std::process::ExitCode;
  5	
  6	use callisto_graph::commands::init::{
  7	    self as scaffold, changesets, BinaryRelease, InitAnswers, InitFacts, InitPackage, Versioning,
  8	};
  9	use callisto_graph::locate::{IgnoreWalkLocator, LocateError};
 10	use callisto_graph::{GraphError, HOSTED_ORIGIN_FORMS};
 11	use callisto_model::{ApplyPermit, BranchName, CommandRunner, InitReport, SCHEMA_VERSION};
 12	use dialoguer::{Confirm, Input, Select};
 13	
 14	use crate::cli::{GlobalArgs, InitArgs, InitVersioning, OutputFormat};
 15	use crate::error::CliError;
 16	use crate::output::emit_report;
 17	use crate::render;
 18	use crate::runner::CliCommandRunner;
 19	use crate::tty;
 20	use crate::workspace::workspace_root;
 21	
 22	pub const VERSIONING_PROMPT: &str = "How should packages be versioned?";
 23	pub const SHIP_PROMPT: &str = "Ship binaries as GitHub release assets?";
 24	pub const PRODUCT_PROMPT: &str = "Which package is the product whose binaries ship?";
 25	pub const TARGETS_PROMPT: &str = "Artifact target triples (comma-separated)";
 26	pub const WRITE_PROMPT: &str = "Write callisto.toml?";
 27	pub const WORKFLOW_PROMPT: &str = "Generate a GitHub Actions release workflow?";
 28	/// Printed instead of the preview when the repository has no commit to plan from.
 29	pub const NO_COMMITS: &str =
 30	    "No commits yet: commit, then run `callisto release --dry-run` to preview the first release.";
 31	/// Printed instead of asking `WORKFLOW_PROMPT` for a workspace no generated workflow covers.
 32	fn workflow_unsupported_note(reason: scaffold::WorkflowUnsupported) -> String {
 33	    format!("Skipping GitHub Actions workflow generation: {reason}.")
 34	}
 35	/// Printed once a generated workflow is written: a merge to `branch` is the release approval.
 36	fn merge_publishes_note(branch: &BranchName) -> String {
 37	    format!(
 38	        "Merging to `{branch}` publishes: require pull requests and reviews on `{branch}` (GitHub → Settings → Rules)."
 39	    )
 40	}
 41	/// Printed once a generated workflow is written: what to do before the first release.
 42	fn next_steps_note(secrets: &[&str]) -> String {
 43	    let secrets = if secrets.is_empty() {
 44	        String::new()
 45	    } else {
 46	        format!(
 47	            "\n  - Add the repository secrets {} (GitHub → Settings → Secrets and variables → Actions).",
 48	            secrets.join(", ")
 49	        )
 50	    };
 51	    format!(
 52	        "\nNext steps:{secrets}\n  - Describe a change with `callisto add`, then commit.\n  - Preview the first release with `callisto release --dry-run`.\n  - A new package's first publish needs a token that can create it: see {FIRST_PUBLISH_URL}."
 53	    )
 54	}
 55	/// Where the registry-by-registry first-publish guidance lives.
 56	const FIRST_PUBLISH_URL: &str = "https://github.com/orin-dx/callisto/blob/main/docs/publishing.md#first-publish";
 57	const VERSIONING_CHOICES: [&str; 2] = [
 58	    "independent: each package has its own version",
 59	    "fixed: every package shares one version",
 60	];
 61	
 62	/// Asks the operator questions; a scripted implementation drives tests.
 63	pub trait Prompter {
 64	    fn select(&mut self, prompt: &str, items: &[String]) -> Result<usize, CliError>;
 65	    fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError>;
 66	    fn input(&mut self, prompt: &str, default: Option<&str>) -> Result<String, CliError>;
 67	}
 68	
 69	struct TerminalPrompter;
 70	
 71	impl Prompter for TerminalPrompter {
 72	    fn select(&mut self, prompt: &str, items: &[String]) -> Result<usize, CliError> {
 73	        Ok(Select::new().with_prompt(prompt).items(items).default(0).interact()?)
 74	    }
 75	
 76	    fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError> {
 77	        Ok(Confirm::new().with_prompt(prompt).default(default).interact()?)
 78	    }
 79	
 80	    fn input(&mut self, prompt: &str, default: Option<&str>) -> Result<String, CliError> {
 81	        let mut input = Input::<String>::new().with_prompt(prompt);
 82	        if let Some(default) = default {
 83	            input = input.default(default.to_owned());
 84	        }
 85	        Ok(input.interact_text()?)
 86	    }
 87	}
 88	
 89	pub fn handle(args: InitArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
 90	    run(
 91	        args,
 92	        global,
 93	        tty::is_interactive(),
 94	        &mut TerminalPrompter,
 95	        &mut std::io::stdout(),
 96	        &mut std::io::stderr(),
 97	        &CliCommandRunner,
 98	    )
 99	}
100	
101	/// Diagnostics queued while `init` runs. `run` emits whatever is still unshown when `init` fails, so an error never
102	/// swallows a warning that explains it.
103	#[derive(Default)]
104	struct Notes {
105	    /// Queued and not yet on stderr.
106	    items: Vec<callisto_model::Diagnostic>,
107	    shown: Vec<callisto_model::Diagnostic>,
108	}
109	
110	impl Notes {
111	    /// Renders the queued notes to stderr and moves them to the shown ones.
112	    fn emit(&mut self, err: &mut dyn Write) -> Result<(), CliError> {
113	        render::render_diagnostics(&self.items, None, &mut &mut *err)?;
114	        self.shown.append(&mut self.items);
115	        Ok(())
116	    }
117	
118	    /// Every note, shown or not, for the JSON report; call `emit` first so each reaches stderr once.
119	    fn take_all(&mut self) -> Vec<callisto_model::Diagnostic> {
120	        let mut all = std::mem::take(&mut self.shown);
121	        all.append(&mut self.items);
122	        all
123	    }
124	}
125	
126	/// `init` against explicit terminal state, prompter, output streams, and command runner.
127	pub fn run<R: CommandRunner>(
128	    args: InitArgs,
129	    global: &GlobalArgs,
130	    interactive: bool,
131	    prompter: &mut dyn Prompter,
132	    out: &mut dyn Write,
133	    err: &mut dyn Write,
134	    runner: &R,
135	) -> Result<ExitCode, CliError> {
136	    let mut notes = Notes::default();
137	    let result = run_queued(
138	        args,
139	        global,
140	        interactive,
141	        prompter,
142	        &mut *out,
143	        &mut *err,
144	        runner,
145	        &mut notes,
146	    );
147	    if result.is_err() {
148	        // The original error wins; a failed stderr write must not replace it.
149	        drop(notes.emit(err));
150	    }
151	    result
152	}
153	
154	#[expect(clippy::too_many_arguments, reason = "init's explicit streams plus the note queue")]
155	fn run_queued<'a, R: CommandRunner>(
156	    args: InitArgs,
157	    global: &GlobalArgs,
158	    interactive: bool,
159	    prompter: &mut dyn Prompter,
160	    out: &'a mut dyn Write,
161	    err: &'a mut dyn Write,
162	    runner: &R,
163	    notes: &mut Notes,
164	) -> Result<ExitCode, CliError> {
165	    validate_flags(&args)?;
166	    // A repository whose manifests all sit in subdirectories has no root yet: init makes the Git toplevel one.
167	    let (root, no_root) = match workspace_root(global, runner) {
168	        Ok(root) => (root, None),
169	        Err(CliError::Locate(LocateError::WorkspaceRootNotFound { start, toplevel })) => (
170	            toplevel.clone(),
171	            Some(LocateError::WorkspaceRootNotFound { start, toplevel }),
172	        ),
173	        Err(error) => return Err(error),
174	    };
175	    let locator = IgnoreWalkLocator::new(&root);
176	    if args.workflow && scaffold::is_initialized(&root)? {
177	        // Answers feed callisto.toml, which stays as it is: refuse them rather than drop them.
178	        // The forge and product flags already require an artifact target.
179	        if args.versioning.is_some() || !args.artifact_targets.is_empty() {
180	            return Err(GraphError::InitAlreadyInitialized {
181	                path: root.join("callisto.toml"),
182	            }
183	            .into());
184	        }
185	        return run_workflow_only(&root, &locator, global, out, err, runner);
186	    }
187	    let facts = scaffold::detect(&root, &locator, runner)?;
188	    if let Some(error) = no_root.filter(|_| facts.packages.is_empty()) {
189	        return Err(error.into());
190	    }
191	    let json = global.format == OutputFormat::Json;
192	    // JSON keeps stdout for the report.
193	    macro_rules! human {
194	        () => {
195	            if json {
196	                &mut *err
197	            } else {
198	                &mut *out
199	            }
200	        };
201	    }
202	    write_facts(&facts, human!())?;
203	
204	    if facts.origin.is_none() {
205	        if args.workflow {
206	            return Err(CliError::InitFlagRequiresOrigin {
207	                flag: "workflow",
208	                not_hosted: facts.origin_not_hosted,
209	            });
210	        }
211	        if !args.artifact_targets.is_empty() {
212	            return Err(CliError::InitFlagRequiresOrigin {
213	                flag: "artifact-target",
214	                not_hosted: facts.origin_not_hosted,
215	            });
216	        }
217	    }
218	    if !interactive && !args.yes {
219	        let mut missing = vec!["--yes"];
220	        missing.extend(missing_flags(&args, &facts));
221	        return Err(CliError::InitRequiresYes { missing });
222	    }
223	    if args.yes {
224	        let missing = missing_flags(&args, &facts);
225	        if !missing.is_empty() {
226	            return Err(CliError::InitMissingFlags { missing });
227	        }
228	    }
229	    let prompting = interactive && !args.yes;
230	    let migration = changesets::migrate(&facts.root, &facts);
231	    // A dry run writes nothing, so it previews with the warning instead of refusing.
232	    let refusing = !migration.public_scoped.is_empty() && !args.yes && !global.dry_run;
233	    // Queued first so a refusal below still shows them; the refusal itself names the access hazard.
234	    notes.items.extend(migration.diagnostics_unless_refused(refusing));
235	    if refusing {
236	        return Err(CliError::InitChangesetsAccess {
237	            packages: migration.public_scoped,
238	        });
239	    }
240	    let mut answers = collect_answers(&args, &facts, prompting, prompter)?;
241	
242	    notes.items.extend(migration.apply_fixed_groups(&mut answers));
243	    if facts.origin.is_none() {
244	        notes.items.push(callisto_model::Diagnostic {
245	            code: callisto_model::DiagnosticCode::InitOriginMissing,
246	            severity: callisto_model::DiagnosticSeverity::Warning,
247	            message: match facts.origin_not_hosted {
248	                Some(reason) => origin_not_hosted_note(reason),
249	                None => ORIGIN_MISSING_NOTE.to_owned(),
250	            },
251	            package: None,
252	            path: None,
253	            escalated_by: None,
254	            governed_by: None,
255	        });
256	    }
257	    let shape = match scaffold::workflow_shape(&facts, answers.binaries.is_some()) {
258	        Err(reason) if args.workflow => {
259	            return Err(GraphError::InitWorkflowUnsupported {
260	                reason: reason.to_string(),
261	            }
262	            .into());
263	        }
264	        Err(reason) => {
265	            let note = workflow_unsupported_note(reason);
266	            notes.items.push(callisto_model::Diagnostic {
267	                code: callisto_model::DiagnosticCode::WorkflowGenerationUnsupported,
268	                severity: callisto_model::DiagnosticSeverity::Warning,
269	                message: note,
270	                package: None,
271	                path: None,
272	                escalated_by: None,
273	                governed_by: None,
274	            });
275	            None
276	        }
277	        Ok(shape) => Some(shape),
278	    };
279	    let want_workflow = match shape {
280	        None => false,
281	        Some(_) if args.workflow => true,
282	        Some(_) if args.no_workflow => false,
283	        Some(_) if prompting && facts.origin.is_some() => prompter.confirm(WORKFLOW_PROMPT, true)?,
284	        // The workflow is GitHub Actions, so only a GitHub origin gets it unasked.
285	        Some(_) => facts.origin_repository.is_some(),
286	    };
287	    // A workflow nobody asked for (the default) never fails `init`: if it cannot be built, say why and go on.
288	    let asked_for_workflow = args.workflow || prompting;
289	    let workflow = match shape.filter(|_| want_workflow) {
290	        Some(shape) => match build_workflow(&facts, shape, migration.base_branch.as_ref(), runner, human!()) {
291	            Ok(built) => Some(built),
292	            Err(error) if !asked_for_workflow => {
293	                let note =
294	                    format!("Skipping the GitHub Actions workflow: {error}. Run `callisto init --workflow` to retry.");
295	                notes.items.push(callisto_model::Diagnostic {
296	                    code: callisto_model::DiagnosticCode::WorkflowGenerationUnsupported,
297	                    severity: callisto_model::DiagnosticSeverity::Warning,
298	                    message: note,
299	                    package: None,
300	                    path: None,
301	                    escalated_by: None,
302	                    governed_by: None,
303	                });
304	                None
305	            }
306	            Err(error) => return Err(error),
307	        },
308	        None => None,
309	    };
310	    if workflow.is_none() {
311	        notes.items.extend(migration.base_branch_unused());
312	    }
313	
314	    let config = scaffold::render_config(&facts, &answers);
315	    let plan = if facts.has_commit {
316	        Some(scaffold::preview(&facts, &config, &locator, runner)?)
317	    } else {
318	        None
319	    };
320	    if config
321	        .lines()
322	        .all(|line| line.trim().is_empty() || line.trim_start().starts_with('#'))
323	    {
324	        writeln!(human!(), "\ncallisto.toml: no settings needed, the defaults apply.")?;
325	    } else {
326	        writeln!(human!(), "\ncallisto.toml:\n{config}")?;
327	    }
328	    match plan {
329	        Some((plan, pending)) => {
330	            writeln!(human!(), "First release preview (`callisto release --dry-run`):")?;
331	            super::release::write_release_preview(plan.as_ref(), OutputFormat::Text, None, human!())?;
332	            // `origin` already has its own note above, so an unbound tag adds nothing.
333	            if let Some(plan) = &plan {
334	                notes.items.extend(plan.diagnostics.clone());
335	            }
336	            let pending = super::release::PendingWork::of(pending);
337	            notes.items.extend(pending.diagnostic());
338	            notes.items.extend(pending.unchecked_diagnostic());
339	        }
340	        None => writeln!(human!(), "{NO_COMMITS}")?,
341	    }
342	    if let Some((_, branch)) = &workflow {
343	        writeln!(human!(), "\n{}", workflow_summary(&facts.root, branch))?;
344	    }
345	
346	    // Computed before any write, so the `.changeset/README.md` existence check sees disk state as-is.
347	    let files = scaffold::init_files(&facts.root, workflow.is_some())?;
348	    let mut report = if global.dry_run {
349	        InitReport {
350	            schema_version: SCHEMA_VERSION,
351	            initialized: false,
352	            config_path: facts.root.join("callisto.toml"),
353	            config,
354	            files,
355	            diagnostics: Vec::new(),
356	        }
357	    } else {
358	        // Said before the write question so a decline keeps them.
359	        notes.emit(&mut *err)?;
360	        if prompting && !prompter.confirm(WRITE_PROMPT, true)? {
361	            if json {
362	                let declined = InitReport {
363	                    schema_version: SCHEMA_VERSION,
364	                    initialized: false,
365	                    config_path: facts.root.join("callisto.toml"),
366	                    config,
367	                    files: Vec::new(),
368	                    diagnostics: notes.take_all(),
369	                };
370	                return finish(&declined, global, out);
371	            }
372	            writeln!(human!(), "Initialization cancelled; nothing was written.")?;
373	            return Ok(ExitCode::SUCCESS);
374	        }
375	        let permit = ApplyPermit::granted_unless_dry_run(global.dry_run).expect("non-dry-run permits writes");
376	        let mut report = scaffold::write(&facts.root, &config, &permit)?;
377	        if let Some((workflow, branch)) = &workflow {
378	            scaffold::write_workflow(&facts.root, workflow, &permit)?;
379	            notes.items.push(announce_workflow(human!(), &facts, branch)?);
380	        }
381	        report.files = files;
382	        report
383	    };
384	    notes.emit(&mut *err)?;
385	    report.diagnostics.extend(notes.take_all());
386	    finish(&report, global, out)
387	}
