426	/// `init --workflow` in a workspace that already has `callisto.toml`: writes only the workflow.
427	fn run_workflow_only<R: CommandRunner>(
428	    root: &std::path::Path,
429	    locator: &IgnoreWalkLocator,
430	    global: &GlobalArgs,
431	    out: &mut dyn Write,
432	    err: &mut dyn Write,
433	    runner: &R,
434	) -> Result<ExitCode, CliError> {
435	    let facts = scaffold::detect_initialized(root, locator, runner)?;
436	    let json = global.format == OutputFormat::Json;
437	    let human: &mut dyn Write = if json { &mut *err } else { &mut *out };
438	    write_facts(&facts, human)?;
439	    if facts.origin.is_none() {
440	        return Err(CliError::InitFlagRequiresOrigin {
441	            flag: "workflow",
442	            not_hosted: facts.origin_not_hosted,
443	        });
444	    }
445	    let shape =
446	        scaffold::workflow_shape(&facts, scaffold::existing_config_ships_binaries(&facts.root)?).map_err(|reason| {
447	            GraphError::InitWorkflowUnsupported {
448	                reason: reason.to_string(),
449	            }
450	        })?;
451	    let base_branch = changesets::base_branch(root);
452	    let (workflow, branch) = build_workflow(&facts, shape, base_branch.as_ref(), runner, human)?;
453	    writeln!(human, "\n{}", workflow_summary(&facts.root, &branch))?;
454	    let mut diagnostics = Vec::new();
455	    if !global.dry_run {
456	        let permit = ApplyPermit::granted_unless_dry_run(global.dry_run).expect("non-dry-run permits writes");
457	        scaffold::write_workflow(&facts.root, &workflow, &permit)?;
458	        diagnostics.push(announce_workflow(human, &facts, &branch)?);
459	    }
460	    let config_path = facts.root.join("callisto.toml");
461	    let config = callisto_model::strict_fs::read_optional(&config_path)
462	        .map_err(|error| GraphError::InitIo {
463	            path: config_path.clone(),
464	            message: error.to_string(),
465	        })?
466	        .unwrap_or_default();
467	    render::render_diagnostics(&diagnostics, None, &mut &mut *err)?;
468	    let report = InitReport {
469	        schema_version: SCHEMA_VERSION,
470	        initialized: !global.dry_run,
471	        config_path,
472	        config,
473	        files: vec![scaffold::workflow_path(&facts.root)],
474	        diagnostics,
475	    };
476	    finish(&report, global, out)
477	}
