479	/// The workflow text and the default branch it triggers on.
480	fn build_workflow<R: CommandRunner>(
481	    facts: &InitFacts,
482	    shape: scaffold::WorkflowShape,
483	    base_branch: Option<&BranchName>,
484	    runner: &R,
485	    human: &mut dyn Write,
486	) -> Result<(String, BranchName), CliError> {
487	    scaffold::ensure_workflow_absent(&facts.root)?;
488	    let branch = match base_branch {
489	        Some(name) => scaffold::DefaultBranch {
490	            name: name.clone(),
491	            source: scaffold::DefaultBranchSource::ChangesetsBaseBranch,
492	        },
493	        None => scaffold::default_branch(runner, &facts.root),
494	    };
495	    writeln!(human, "  default branch: {} (from {})", branch.name, branch.source)?;
496	    let version = semver::Version::parse(env!("CARGO_PKG_VERSION")).expect("Cargo package versions are semver");
497	    let commit = scaffold::resolve_release_commit(runner, &facts.root, &version)?;
498	    let content = scaffold::render_workflow(facts, shape, &branch.name, &commit, &version);
499	    Ok((content, branch.name))
500	}
