527	fn write_facts(facts: &InitFacts, out: &mut dyn Write) -> Result<(), CliError> {
528	    let ecosystems: Vec<&str> = facts.ecosystems.iter().map(|ecosystem| ecosystem.prefix()).collect();
529	    writeln!(out, "Detected:")?;
530	    writeln!(out, "  ecosystems: {}", ecosystems.join(", "))?;
531	    let origin = match (&facts.origin, facts.origin_not_hosted.is_some()) {
532	        (Some(origin), _) => origin.as_str(),
533	        (None, true) => "not hosted",
534	        (None, false) => "none",
535	    };
536	    writeln!(out, "  origin: {origin}")?;
537	    writeln!(out, "  packages:")?;
538	    for package in &facts.packages {
539	        let tag = package.last_tag.as_ref().map_or("none", |tag| tag.as_str());
540	        write!(out, "    {} {} (last tag: {tag}", package.id, package.version)?;
541	        if package.is_binary() {
542	            write!(out, "; binary: {}", package.bin_names.join(", "))?;
543	        }
544	        writeln!(out, ")")?;
545	    }
546	    Ok(())
547	}
