126	/// `init` against explicit terminal state, prompter, output streams, and command runner.
127	pub fn run<R: CommandRunner>(
128	    args: InitArgs,
129	    global: &GlobalArgs,
130	    interactive: bool,
131	    prompter: &mut dyn Prompter,
132	    out: &mut dyn Write,
133	    err: &mut dyn Write,
134	    runner: &R,
135	) -> Result<ExitCode, CliError> {
136	    let mut notes = Notes::default();
137	    let result = run_queued(
138	        args,
139	        global,
140	        interactive,
141	        prompter,
142	        &mut *out,
143	        &mut *err,
144	        runner,
145	        &mut notes,
146	    );
147	    if result.is_err() {
148	        // The original error wins; a failed stderr write must not replace it.
149	        drop(notes.emit(err));
150	    }
151	    result
152	}
