514	/// Rejects flag combinations invalid regardless of workspace facts.
515	fn validate_flags(args: &InitArgs) -> Result<(), CliError> {
516	    if args.workflow && args.no_workflow {
517	        return Err(CliError::InitWorkflowFlagsConflict);
518	    }
519	    if args.artifact_targets.is_empty() && args.product_package.is_some() {
520	        return Err(CliError::InitFlagRequiresArtifactTarget {
521	            flag: "product-package",
522	        });
523	    }
524	    Ok(())
525	}
