562	fn missing(flag: &'static str) -> CliError {
563	    CliError::InitMissingFlags { missing: vec![flag] }
564	}
565	
566	fn collect_answers(
567	    args: &InitArgs,
568	    facts: &InitFacts,
569	    prompting: bool,
570	    prompter: &mut dyn Prompter,
571	) -> Result<InitAnswers, CliError> {
572	    let versioning = match args.versioning {
573	        Some(InitVersioning::Fixed) => Versioning::Fixed,
574	        Some(InitVersioning::Independent) => Versioning::Independent,
575	        // Fixed and independent mean the same for one package, so only several packages are asked.
576	        None if prompting && facts.packages.len() > 1 => {
577	            let choices: Vec<String> = VERSIONING_CHOICES.iter().map(|choice| (*choice).to_owned()).collect();
578	            match prompter.select(VERSIONING_PROMPT, &choices)? {
579	                0 => Versioning::Independent,
580	                _ => Versioning::Fixed,
581	            }
582	        }
583	        None => Versioning::Independent,
584	    };
585	    let no_binaries = InitAnswers {
586	        versioning,
587	        binaries: None,
588	        fixed_groups: Vec::new(),
589	    };
590	
591	    let binaries: Vec<&InitPackage> = facts.binary_packages().collect();
592	    if binaries.is_empty() && !args.artifact_targets.is_empty() {
593	        if let Some(package) = facts.unsupported_artifact_packages().next() {
594	            return Err(GraphError::InitUnsupportedArtifactBuilder {
595	                package: package.id.clone(),
596	                ecosystem: package
597	                    .id
598	                    .split_once('/')
599	                    .map_or("unknown", |(ecosystem, _)| ecosystem)
600	                    .to_owned(),
601	            }
602	            .into());
603	        }
604	        return Err(GraphError::InitNoBinaryPackage.into());
605	    }
606	    let requested_product = args
607	        .product_package
608	        .as_deref()
609	        .map(|name| facts.product_package(name))
610	        .transpose()?;
611	    if binaries.is_empty() {
612	        return Ok(no_binaries);
613	    }
614	    // No `origin`: the forge question below has nothing to validate a repository against, so
615	    // shipping is never offered (skips straight to `no_binaries`); `--artifact-target` without
616	    // `origin` is already rejected up front in `run`.
617	    let ship = !args.artifact_targets.is_empty()
618	        || (facts.origin.is_some() && prompting && prompter.confirm(SHIP_PROMPT, false)?);
619	    if !ship {
620	        return Ok(no_binaries);
621	    }
622	    // A release goes to origin's GitHub repository, so shipping needs one.
623	    if facts.origin_repository.is_none() {
624	        return Err(GraphError::ReleaseForgeRepositoryMissing.into());
625	    }
626	
627	    let product = match (requested_product, binaries.as_slice()) {
628	        (Some(product), _) => product,
